// A stand-in for api.github.com, for smoke-token.sh. It spends nothing and
// talks to nobody: it verifies the App JWT epito signs against a throwaway
// public key generated by the test, and answers the two endpoints the mint
// uses. Verifying the signature here is the point — it is what proves the
// RS256 JWT epito builds by hand is one GitHub would actually accept.
//
//   node test/github-stub.mjs <port> <public-key.pem> <log.jsonl> [mode] [private-key.pem]
//
// The fifth argument makes it a stand-in for the OTHER half of the identity
// leg as well: `epito deploy` exchanges a one-shot code for an App, and the
// private key GitHub hands back at that moment is the key every later mint
// signs with. Give this stub the private half and it returns it from
// POST /app-manifests/<code>/conversions, so one process can play GitHub
// across a deploy AND the mint that follows it — which is the only way to
// prove the two halves agree about where the key lives.
//
// modes: ok (default) | not-installed (404 on installation lookup)
//        | bad-app (401 on installation lookup) | refuse-perms (422 on mint)
//        | thin-perms (installed, but granted less than the manifest's scopes)
//        | no-bot (404 on GET /app, so the commit-identity lookup fails and
//                 the run must degrade loudly instead of stopping)
//
// $STUB_APP_OWNER ("<login>:<User|Organization>", default "acme:User") sets
// who GitHub says owns the App. It is an environment variable rather than a
// mode because it composes with every mode above: an org-owned App whose
// installation is ALSO short of a permission is one case, not two, and an
// App's settings pages live at a different path for each owner type.
import { createServer } from "node:http";
import { createVerify } from "node:crypto";
import { readFileSync, appendFileSync } from "node:fs";

const [port, pubPath, logPath, mode = "ok", privPath] = process.argv.slice(2);
const pub = readFileSync(pubPath, "utf8");
// The App `epito deploy` creates here. One id, one slug, so the mint that
// follows the deploy is verifiably minting for the App the deploy made.
const CONVERTED = { id: 707070, slug: "epito-seat-707070" };
const record = (o) => appendFileSync(logPath, JSON.stringify(o) + "\n");

const [ownerLogin, ownerType] = (process.env.STUB_APP_OWNER ?? "acme:User").split(":");

const unb64 = (s) => Buffer.from(s.replace(/-/g, "+").replace(/_/g, "/"), "base64");

// The token this stub mints, and the only installation credential it honours.
const INSTALLATION_TOKEN = "ghs_STUBTOKEN0000000000000000000000000000";

// Returns { ok: true, claims } or { ok: false, why }.
function verifyJwt(auth) {
  const m = /^Bearer (.+)$/.exec(auth ?? "");
  if (!m) return { ok: false, why: "no bearer token" };
  const parts = m[1].split(".");
  if (parts.length !== 3) return { ok: false, why: "not three JWT segments" };
  const [h, p, sig] = parts;
  const header = JSON.parse(unb64(h).toString());
  if (header.alg !== "RS256") return { ok: false, why: `alg is ${header.alg}, GitHub requires RS256` };
  const v = createVerify("RSA-SHA256");
  v.update(`${h}.${p}`);
  if (!v.verify(pub, unb64(sig))) return { ok: false, why: "signature does not verify against the App's public key" };
  const claims = JSON.parse(unb64(p).toString());
  const now = Math.floor(Date.now() / 1000);
  if (!claims.iss) return { ok: false, why: "no iss (App id)" };
  if (!(claims.exp > now)) return { ok: false, why: "already expired" };
  if (claims.exp - claims.iat > 600) return { ok: false, why: `lifetime ${claims.exp - claims.iat}s exceeds GitHub's 10 minute maximum` };
  if (claims.iat > now) return { ok: false, why: "iat is in the future; GitHub rejects clock skew" };
  return { ok: true, claims };
}

createServer((req, res) => {
  let body = "";
  req.on("data", (d) => (body += d));
  req.on("end", () => {
    const send = (code, obj) => { res.writeHead(code, { "content-type": "application/json" }); res.end(JSON.stringify(obj)); };

    // POST /app-manifests/<code>/conversions is the one endpoint here that
    // takes no credential at all, because at that instant the agent HAS no
    // credential: possession of the single-use code is the whole proof. It is
    // checked before the JWT for exactly that reason — requiring a signature
    // here would be the stub being stricter than GitHub, which teaches epito
    // the wrong lesson.
    const conv = /^\/app-manifests\/([^/]+)\/conversions$/.exec(req.url);
    if (req.method === "POST" && conv) {
      record({ method: req.method, url: req.url, jwtOk: null, why: null, iss: null, body: body || null });
      if (!privPath) return send(500, { message: "stub: started without a private key, so it cannot convert an App manifest" });
      if (conv[1] === "expired") return send(404, { message: "Not Found" });
      return send(201, {
        ...CONVERTED,
        name: "acme-bot-acme",
        owner: { login: "acme" },
        html_url: `https://github.com/apps/${CONVERTED.slug}`,
        pem: readFileSync(privPath, "utf8"),
        webhook_secret: null,
        client_id: "Iv1.stubclientid",
        client_secret: "stub-client-secret-not-a-real-one",
      });
    }

    const jwt = verifyJwt(req.headers.authorization);

    // GET /users/<login> is the one endpoint the mint reaches as the
    // INSTALLATION rather than as the App — GitHub does not accept an App JWT
    // there, so neither does this. Checking it here is the point: it is what
    // proves epito sends the right kind of credential to the right endpoint.
    const user = /^\/users\/(.+)$/.exec(req.url);
    if (req.method === "GET" && user) {
      const asInstallation = req.headers.authorization === `Bearer ${INSTALLATION_TOKEN}`;
      record({ method: req.method, url: req.url, jwtOk: false, why: asInstallation ? null : "not the installation token", iss: null, body: null });
      if (!asInstallation) return send(401, { message: "stub: /users wants the installation token, not the App JWT" });
      const login = decodeURIComponent(user[1]);
      return send(200, { login, id: 99001, type: "Bot" });
    }

    record({ method: req.method, url: req.url, jwtOk: jwt.ok, why: jwt.why ?? null, iss: jwt.claims?.iss ?? null, body: body || null });
    if (!jwt.ok) return send(401, { message: `stub rejected the JWT: ${jwt.why}` });

    // GET /app: who this App is. The slug is what names the bot user, so it
    // is derived from the App id the JWT claims rather than fixed — a roster
    // with two Apps must not look like one.
    if (req.method === "GET" && req.url === "/app") {
      if (mode === "no-bot") return send(404, { message: "Not Found" });
      // `owner` is sent by the real endpoint and is the half that decides
      // where this App's settings pages are, so a stub that omitted it would
      // let a wrong URL pass a test.
      return send(200, {
        id: Number(jwt.claims.iss),
        slug: `epito-seat-${jwt.claims.iss}`,
        name: `epito seat ${jwt.claims.iss}`,
        owner: { login: ownerLogin, type: ownerType },
      });
    }

    const inst = /^\/repos\/([^/]+)\/([^/]+)\/installation$/.exec(req.url);
    if (req.method === "GET" && inst) {
      if (mode === "not-installed") return send(404, { message: "Not Found" });
      if (mode === "bad-app") return send(401, { message: "A JSON web token could not be decoded" });
      // `permissions` is what the App was actually granted on this account,
      // and GitHub does send it here. It is the half `epito doctor --deep`
      // compares against [identity].scopes, because an installation can only
      // hand out what it was granted and the mint learns that as a 422.
      // thin-perms is that case: installed, and granted read where the
      // manifest's scopes need write.
      const permissions = mode === "thin-perms"
        ? { metadata: "read", contents: "read" }
        : { metadata: "read", contents: "write", pull_requests: "write", issues: "write" };
      return send(200, { id: 4242, account: { login: inst[1] }, repository_selection: "selected", permissions });
    }

    const mint = /^\/app\/installations\/(\d+)\/access_tokens$/.exec(req.url);
    if (req.method === "POST" && mint) {
      if (mode === "refuse-perms") return send(422, { message: "There is at least one repository that does not exist or is not accessible to the parent installation" });
      const asked = JSON.parse(body || "{}");
      return send(201, {
        token: INSTALLATION_TOKEN,
        expires_at: new Date(Date.now() + 3600_000).toISOString(),
        permissions: asked.permissions ?? {},
        repository_selection: asked.repositories ? "selected" : "all",
      });
    }
    send(404, { message: `stub has no route for ${req.method} ${req.url}` });
  });
}).listen(Number(port), "127.0.0.1", function () {
  // The BOUND port, not the asked-for one, so a caller may pass 0 and read the
  // real one back off this line instead of racing for a fixed port.
  console.log(`github-stub on ${this.address().port} (${mode})`);
});
